// bring in Verus attributes (`#[requires]`, `#[ensures]`, etc.)
use verus::*;

/// Returns true exactly for those months that have 30 days:
///    April (4), June (6), September (9), November (11)
#[requires(1 <= month && month <= 12)]
#[ensures(
    // the result is true exactly when month ∈ {4,6,9,11}
    result == (month == 4 || month == 6 || month == 9 || month == 11)
)]
fn is_month_with_30_days(month: i32) -> bool {
    matches!(month, 4 | 6 | 9 | 11)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_months_with_30_days() {
        assert!(is_month_with_30_days(4));  // April
        assert!(is_month_with_30_days(6));  // June
        assert!(is_month_with_30_days(9));  // September
        assert!(is_month_with_30_days(11)); // November
    }

    #[test]
    fn test_other_months() {
        for month in &[1, 2, 3, 5, 7, 8, 10, 12] {
            assert!(!is_month_with_30_days(*month));
        }
    }
}